\begin{tikzpicture}[every node/.style={font=\large}, scale=0.72]
\draw[->] (0,0)--(0,9.4);
\draw[->] (0,0)--(13.5,0);
\foreach \y/\lbl in {2/\frac{1}{12},4/\frac{2}{12},6/\frac{3}{12},8/\frac{4}{12}} {\draw (-0.2,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.2,\y) {$\lbl$};}
\node[left,font=\scriptsize] at (-0.2,0) {$0$};
\draw (0.8,0) rectangle (2.3,4);
\draw (3.1,0) rectangle (4.6,6);
\draw (5.4,0) rectangle (6.9,8);
\draw (7.7,0) rectangle (9.2,4);
\draw (10.0,0) rectangle (11.5,2);
\node[below,font=\scriptsize] at (1.55,0) {$5$};
\node[below,font=\scriptsize] at (3.85,0) {$6$};
\node[below,font=\scriptsize] at (6.15,0) {$7$};
\node[below,font=\scriptsize] at (8.45,0) {$8$};
\node[below,font=\scriptsize] at (10.75,0) {$9$};
